constraints:
2 <= N <= 10^{6}

expected time complexity: O(N*loglog(N))
expected auxiliary space: O(N)

standard_solution_code:
import math

class Solution:

	def getPrimes(self, N):
		result = []

		def checkPrime(n):
			for i in range(2, n // 2):
				if n % i == 0:
					return False
			return True
		if checkPrime(N - 2) and N - 2 > 0:
			return [2, N - 2]
		for i in range(3, int(math.sqrt(N)) + 1, 2):
			if checkPrime(i) and checkPrime(N - i):
				return [i, N - i]
		return [-1, -1]
